window.TEXTP["76.22"] = [[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 108; «аль-Манасик», стр. 48. </b>"],["sep",""],["h2","ВОПРОС № 13: ОТПРАВЛЕНИЕ В ПУТЬ ДЛЯ ПОСЕЩЕНИЯ МОГИЛ ПРОРОКОВ И ПРАВЕДНИКОВ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 108; «аль-Манасик», стр. 48. </b>"],["sep",""],["p","ВОПРОС № 14: НЕКОТОРЫЕ ЛЮДИ ДЕЛАЮТ ТАК: ЕСЛИ ЗАМУЖНЯЯ ЖЕНЩИНА ХОЧЕТ ОТПРАВИТЬСЯ В ХАДЖ, НО С НЕЙ НЕТ БЛИЗКОГО РОДСТВЕННИКА (МАХРАМ), ТО ДРУГОЙ МУЖЧИНА ЗАКЛЮЧАЕТ С НЕЙ «БРАЧНЫЙ ДОГОВОР» (НИКАХ), ЧТОБЫ СТАТЬ ЕЙ МАХРАМОМ НА ВРЕМЯ ХАДЖА<sup class=\"fn\">656</sup>"],["n",[[656,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Это – одно из самых скверных новшеств, потому что, во-первых, это ухищрение против шариата, а, во-вторых, эти люди сами подвергают себя совершению мерзости, как это очевидно всем». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 108; «аль-Манасик», стр. 48. </b>"],["h3","<b>И здесь есть ещё два похожих новшества</b>:"],["li","•","Мужчина объявляет себя братом посторонней женщины и считает, что так он становится для неё махрамом, а затем она относится к нему так же, как относится к своим ближайшим родственникам."],["li","•","Некоторые женщины отправляются в хадж, как они считают, с группой надёжных женщин, но без близкого родственника (махрам). Или же, например, с одной из этих женщин есть близкий родственник (махрам), и они думают, что является махрамом для них всех."],["p","<b>См. «аль-Манасик», стр. 49. </b>"],["sep",""],["h2","ВОПРОС № 15: ВЗИМАНИЕ НАЛОГОВ С ПАЛОМНИКОВ, КОТОРЫЕ ОТПРАВЛЯЮТСЯ ДЛЯ ВЫПОЛНЕНИЯ ОБЯЗАТЕЛЬНОГО ХАДЖА"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 109; «аль-Манасик», стр. 49. </b>"],["sep",""],["p","ВОПРОС № 16: КАЖДЫЙ РАЗ, КАК ПАЛОМНИК ОСТАНАВЛИВАЕТСЯ НА ПРИВАЛ, ОН СОВЕРШАЕТ МОЛИТВУ В ДВА РАКААТА И ГОВОРИТ: «О АЛЛАХ! ДАРУЙ МНЕ БЛАГОДАТНОЕ ПРИСТАНИЩЕ, ВЕДЬ ТЫ – ЛУЧШИЙ ИЗ ТЕХ, КТО ДАРУЕТ ПРИСТАНИЩА!»."],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 109; «аль-Манасик», стр. 49. </b>"],["sep",""],["p","ВОПРОС № 17: КАЖДЫЙ РАЗ, КАК ПАЛОМНИК ОСТАНАВЛИВАЕТСЯ НА ПРИВАЛ, ОН ОДИННАДЦАТЬ РАЗ ЧИТАЕТ СУРУ «АЛЬ-ИХЛЯС», ЗАТЕМ ОДИН РАЗ «АЯТ АЛЬ-КУРСИЙ», ЗАТЕМ ОДИН РАЗ 67-ОЙ АЯТ ИЗ СУРЫ «АЗ-ЗУМАР»"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 109; «аль-Манасик», стр. 49. </b>"],["sep",""],["h2","ВОПРОС № 18: НЕКОТОРЫЕ ПУТНИКИ СЧИТАЮТ, ЧТО НУЖНО ПОЕСТЬ ЗЕЛЕНЬ, ВЫРАЩЕННУЮ НА КАЖДОЙ ЗЕМЛЕ, КОТОРУЮ ОНИ ПРОХОДЯТ<sup class=\"fn\">657</sup>"],["n",[[657,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Это назвал желательным автор книги \"Шарх аш-Шир′ат\", 381, но желательность – это религиозное постановление, которое должно быть подкреплено доводом. В качестве довода некоторые привели хадис: \"Кто поел зелень с (определенной) земли, тому не навредит её вода\". Имеется в виду лук. Этот хадис является странным, и мы не видели его нигде, кроме книги \"ан-Нихая\" Ибн уль-Асира. Но в этой книге много хадисов, у которых нет никакой основы». </i>"]]]],[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 109; «аль-Манасик», стр. 49. </b>"],["sep",""],["p","ВОПРОС № 19: НЕКОТОРЫЕ ЛЮДИ СПЕЦИАЛЬНО НАПРАВЛЯЮТСЯ В ОПРЕДЕЛЕННЫЕ МЕСТА, ЖЕЛАЯ ОБРЕСТИ БЛАГО ЧЕРЕЗ ПОСЕЩЕНИЕ ЭТИХ МЕСТ, НО ПРИ ЭТОМ ШАРИАТ НЕ НАЗВАЛ ТАКОЕ ПОСЕЩЕНИЕ ЖЕЛАТЕЛЬНЫМ. НАПРИМЕР, РЕЧЬ ИДЁТ О ПОСЕЩЕНИИ ТЕХ МЕСТ, В КОТОРЫХ, КАК ГОВОРЯТ, ОСТАЛИСЬ СЛЕДЫ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ)<sup class=\"fn\">658</sup>. НАПРИМЕР, ТАК ГОВОРЯТ О СКАЛЕ В ИЕРУСАЛИМЕ, МЕЧЕТИ «АЛЬ-КАДАМ» В ДАМАСКЕ, А ТАКЖЕ ТЕХ МЕСТАХ, КОТОРЫЕ НАЗЫВАЮТ МЕСТАМИ ЗАХОРОНЕНИЙ ПРОРОКОВ И ПРАВЕДНИКОВ"],["n",[[658,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Достоверно передано, что однажды ′Умар (да будет доволен им Аллах) увидел, что люди по пути в хадж поспешили к какому-то месту, и спросил: \"Что это (за место)?\". Люди сказали: \"Это – место, где совершил молитву посланник Аллаха (да благословит его Аллах и приветствует)\". Тогда он сказал: \"Вот так погибли обладатели Писания. Они превращали следы своих пророков в храмы. Если кого-то из вас застигла молитва в этом месте, то пусть молится, а иначе пусть не совершает молитву\". См. нашу книгу \"Тахзир ас-саджид\", стр. 97». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 109; «аль-Манасик», стр. 49. </b>"],["sep",""],["h2","ВОПРОС № 20: НЕКОТОРЫЕ ПАЛОМНИКИ, КОГДА ПРОХОДЯТ МИМО ТАБУКА, ОБНАЖАЮТ СВОЁ ОРУЖИЕ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 110; «аль-Манасик», стр. 49. </b>"],["sep",""],["h2","ГЛАВА № 2 – НОВШЕСТВА, СВЯЗАННЫЕ С ИХРАМОМ<sup class=\"fn\">659</sup>, ТАЛЬБИЕЙ<sup class=\"fn\">660</sup> И Т. П."],["n",[[659,"Ихрам – это состояние паломника, совершающего хадж или ‘умру. Находясь в этом состоянии, он должен соблюдать ряд запретов, от которых свободны все остальные мусульмане. Этим термином также называют одеяние паломника. Более подробно этот вопрос освещен в специализированных книгах по фикху."],[660,"Тальбия – это особые слова, произносимые паломником. Он говорит: <b><i>«Вот я перед Тобой, о Аллах, вот я перед Тобой! Вот я перед Тобой, и нет у Тебя сотоварищей! Вот я перед Тобой! Поистине, хвала и милость принадлежат тебе, (а также) и власть. Нет у Тебя сотоварища!».</i></b> Эти слова передаются в хадисе у аль-Бухари, 5915 и Муслима, 1184."]]],["h2","ВОПРОС № 1: НЕКОТОРЫЕ ЛЮДИ ВО ВРЕМЯ ИХРАМА НАДЕВАЮТ СПЕЦИАЛЬНЫЕ САНДАЛИИ, КАЧЕСТВА КОТОРЫХ ОПИСАНЫ В ОПРЕДЕЛЕННЫХ КНИГАХ<sup class=\"fn\">661</sup>"],["n",[[661,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Дело в том, что подобные условия не пришли в Сунне. Религия Аллаха является лёгкой. А всякое условие, которого нет в Книге Аллаха, является ложным, даже если это будет сто условий, как это пришло в достоверном сборнике аль-Бухари. Пророк (да благословит его Аллах и приветствует) установил в отношении сандалий только одно условие – чтобы они не закрывали щиколотки. Пророк (да благословит его Аллах и приветствует) сказал: </i><b><i>\"Пусть человек в состоянии ихрама не надевает хуффы (кожаные носки), кроме тех, кто не сможет найти сандалии. Пусть такой человек носит кожаные носки, обрезав их так, чтобы верхние края не доходили до щиколоток\". </i></b><i>Передали аль-Бухари и Муслим». </i>"]]]],[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 109; «аль-Манасик», стр. 50. </b>"],["sep",""],["h2","ВОПРОС № 2: ВСТУПЛЕНИЕ В ИХРАМ РАНЬШЕ МИКАТА<sup class=\"fn\">662</sup>"],["n",[[662,"Микат – это то место, которое установил пророк (да благословит его Аллах и приветствует) для вступления в состояние ихрама. Поэтому нужно вступать в ихрам именно в этом месте, следуя его примеру. Здесь в примечаниях шейх аль-Альбани сказал: <i>«Потому что это противоречит Сунне. Что касается хадиса: \"Из совершенства хаджа то, что ты вступаешь в ихрам у дома своей семьи\", то он является отвергаемым (мункар), как я разъяснил это в \"ас-Сильсиля ад-да′ифа\", № 210. К тому же от пророка (да благословит его Аллах и приветствует) и от целой группы сподвижников (например, среди них ′Умар и ′Усман) передано то, что противоречит этому хадису. </i> <i>И как прекрасно то, что передал аль-Харауи и другие ученые от Ибн ′Уейны, который рассказывал: «Однажды к Малику ибн Анасу пришёл некий человек и сказал: \"О Абу ′Абдуллах! Откуда мне вступать в ихрам?\". (Малик) ответил: \"Из Зуль-Хулейфы (микат для жителей Медины). Ведь именно там вступал в ихрам посланник Аллаха (да благословит его Аллах и приветствует)\". Тот человек сказал: \"Но я хочу вступить в ихрам в этой мечети, возле могилы пророка (да благословит его Аллах и приветствует)\". (Малик) сказал: \"Не делай так! Я боюсь, что ты впадёшь в смуту!\". Тот сказал: \"А какая тут может быть смута?! Я всего лишь добавлю несколько миль\". (Малик) сказал: «А какая смута хуже той, когда ты считаешь, что сумел обрести достоинство, в отношении которого проявил небрежность посланник Аллаха (да благословит его Аллах и приветствует)?! Я слышал, что Аллах говорил: </i><b>\"Пусть же остерегаются те, которые противятся его</b> [пророка] <b>приказу, как бы их не постигла смута или не постигли их мучительные страдания\". </b><i>(Сура \"ан-Нур\", аят 63)». </i> См. также вопрос № 22 в пятой главе (НОВШЕСТВА, СВЯЗАННЫЕ С ДОПОЛНИТЕЛЬНЫМИ МОЛИТВАМИ) двенадцатого раздела."]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 111; «аль-Манасик», стр. 50. </b>"],["sep",""],["h2","ВОПРОС № 3: ОБНАЖЕНИЕ (ИДТЫБА′) ПЛЕЧА ВО ВРЕМЯ ВСТУПЛЕНИЯ В ИХРАМ<sup class=\"fn\">663</sup>"],["n",[[663,"«Идтыба′» заключается в том, что человек пропускает один край своей накидки под правой подмышкой, оставляя правое плечо оголенным. Другим же краем накидки он закрывает свое левое плечо, а также грудь и спину. Это действие узаконено лишь во время обхода вокруг Каабы (таваф). Поэтому неправильно делать это, находясь в микате."]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 111; «аль-Манасик», стр. 50. </b>"],["sep",""],["h2","ВОПРОС № 4: ПРОИЗНЕСЕНИЕ НАМЕРЕНИЯ ВСЛУХ"]],[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 112; «аль-Манасик», стр. 50. </b>"],["sep",""],["h2","ВОПРОС № 5: СОВЕРШЕНИЕ ХАДЖА МОЛЧА, КОГДА ПАЛОМНИК НАМЕРЕННО НИ С КЕМ НЕ РАЗГОВАРИВАЕТ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 112; «аль-Манасик», стр. 50. </b>"],["sep",""],["h2","ВОПРОС № 6: ГРУППОВОЕ ПРОИЗНЕСЕНИЕ ТАЛЬБИИ В ОДИН ГОЛОС"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 112; «аль-Манасик», стр. 50. </b>"],["sep",""],["h2","ВОПРОС № 7: ПРОИЗНЕСЕНИЕ СЛОВ «АЛЛАХУ АКБАР» И «ЛЯ ИЛЯХА ИЛЛЯ ЛЛАХ» ВМЕСТО ТАЛЬБИИ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 112; «аль-Манасик», стр. 50. </b>"],["sep",""],["p","ВОПРОС № 8: ПРОИЗНЕСЕНИЕ ПОСЛЕ ТАЛЬБИИ СЛЕДУЮЩИХ СЛОВ: «О АЛЛАХ! ПОИСТИНЕ, Я ХОЧУ СОВЕРШИТЬ ХАДЖ, ОБЛЕГЧИ ЖЕ МНЕ ЕГО И ПОМОГИ МНЕ ВЫПОЛНИТЬ ЭТУ ОБЯЗАННОСТЬ, И ПРИМИ ОТ МЕНЯ. О АЛЛАХ! Я НАМЕРЕВАЮСЬ ВЫПОЛНИТЬ ОБЯЗАННОСТЬ ХАДЖА ПЕРЕД ТОБОЙ, ПОЭТОМУ СДЕЛАЙ МЕНЯ…» И Т. Д<sup class=\"fn\">664</sup>."],["n",[[664,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Аль-Газали сказал, что это является желательным. Что касается аль-Баджури, то он сказал (1/329), что это сунна. Наверное, он имел в виду, что это сунна (обычай) шейхов. В противном случае, каждый, у кого есть познания о Сунне, знает, что у этой мольбы нет никакой основы». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 112; «аль-Манасик», стр. 50. </b>"],["sep",""],["p","ВОПРОС № 9: ОТПРАВЛЕНИЕ В МЕЧЕТИ, КОТОРЫЕ В МЕККЕ И ВОКРУГ НЕЕ, КРОМЕ ЗАПОВЕДНОЙ МЕЧЕТИ (АЛЬ-ХАРАМ). НАПРИМЕР, НЕКОТОРЫЕ ЛЮДИ ОТПРАВЛЯЮТСЯ В МЕЧЕТЬ, КОТОРАЯ У АС-САФЫ, В МЕЧЕТЬ, КОТОРАЯ У ПОДНОЖИЯ АБУ КУБЕЙСА, И В ДРУГИЕ МЕЧЕТИ, КОТОРЫЕ БЫЛИ ПОСТРОЕНЫ НА СЛЕДАХ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ)"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 112; «аль-Манасик», стр. 50. </b>"],["sep",""],["p","ВОПРОС № 10: ПОСЕЩЕНИЕ ГОР И МЕСТ, КОТОРЫЕ ВОКРУГ МЕККИ. НАПРИМЕР, ПАЛОМНИКИ ПОСЕЩАЮТ ГОРУ ХИРА И ГОРУ, КОТОРАЯ ВОЗЛЕ МИНЫ, ГДЕ, КАК ГОВОРЯТ, ИБРАХИМ ПРИНЁС ЖЕРТВУ АЛЛАХУ, И Т. Д."],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 113; «аль-Манасик», стр. 50. </b>"],["sep",""],["h2","ВОПРОС № 11: СТРЕМЛЕНИЕ СОВЕРШИТЬ МОЛИТВУ В МЕЧЕТИ ′АИШИ, КОТОРАЯ НАХОДИТСЯ В ТАН′ИМЕ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 113; «аль-Манасик», стр. 50. </b>"],["sep",""],["h2","ВОПРОС № 12: НЕКОТОРЫЕ ЛЮДИ «КРЕСТЯТСЯ» ПЕРЕД КААБОЙ<sup class=\"fn\">665</sup>"],["n",[[665,"Шейх аль-Альбани (да помилует его Всевышний Аллах) в примечаниях к «аль-Манасик», стр. 50, сказал: <i>«Вероятно, речь идёт о тех, кто (при виде Каабы) протирает двумя руками лицо и грудь, так, что по форме это напоминает крест». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 113; «аль-Манасик», стр. 50. </b>"],["sep",""],["h2","ГЛАВА № 3 – НОВШЕСТВА, СВЯЗАННЫЕ С ОБХОДОМ ВОКРУГ КААБЫ (ТАВАФ)"],["h2","ВОПРОС № 1: СОВЕРШЕНИЕ ПОЛНОГО ОМОВЕНИЯ (ГУСЛЬ) ПЕРЕД ОБХОДОМ ВОКРУГ КААБЫ (ТАВАФ)"]],[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 113; «аль-Манасик», стр. 51. </b>"],["sep",""],["p","ВОПРОС № 2: НЕКОТОРЫЕ ЛЮДИ УБЕЖДЕНЫ В ТОМ, ЧТО ЕСТЬ ОСОБЫЙ ЗИКР (ФОРМА ПОМИНАНИЯ АЛЛАХА), КОТОРЫЙ ПРИШЁЛ ОТ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) И КОТОРЫЙ НЕОБХОДИМО ПРОИЗНОСИТЬ ВО ВРЕМЯ ОБХОДА ВОКРУГ КААБЫ"],["h3","<b>Сказал шейх ислама (Ибн Теймия):</b>"],["p","«Во время обхода вокруг Каабы (таваф) нет определенного зикра от пророка (да благословит его Аллах и приветствует). Он не приказывал произносить что-то конкретное, не произносил что-то конкретное сам и не обучал этому других. Во время обхода вокруг Каабы (таваф) человек произносит любые религиозные мольбы. А что касается того, что упоминают многие люди из определенных мольб, которые нужно произносить возле определенных мест Каабы (например, возле Мизаба), то этому нет никакой основы»."],["p","См. «Манасик аль-хадж уаль ′умра», стр. 23."],["sep",""],["p","ВОПРОС № 3: НЕКОТОРЫЕ ЛЮДИ ВО ВРЕМЯ ТАВАФА НАДЕВАЮТ НОСКИ ИЛИ ЧТО-ТО ПОДОБНОЕ, ЧТОБЫ НЕ НАСТУПАТЬ ПТИЧИЙ ПОМЁТ, ИЛИ СКРЫВАЮТ РУКИ ПОД ОДЕЯНИЕМ, ЧТОБЫ НЕ ПРИКОСНУТЬСЯ К ЖЕНЩИНЕ<sup class=\"fn\">666</sup>"],["n",[[666,"Сказал шейх ислама Ибн Теймия в «аль-Маджму′», 2/374: <i>«Кто поступает так, тот противоречит Сунне. Ведь пророк (да благословит его Аллах и приветствует) и его сподвижники, и таби′ины совершали обход вокруг Каабы, и в их время в Мекке тоже бывали птицы». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 113; «аль-Манасик», стр. 51. </b>"],["sep",""],["p","ВОПРОС № 4: КОГДА ЧЕЛОВЕК В СОСТОЯНИИ ИХРАМА ВСТУПАЕТ В ЗАПОВЕДНУЮ МЕЧЕТЬ (АЛЬ-ХАРАМ), ОН СОВЕРШАЕТ МОЛИТВУ ПРИВЕТСТВИЯ МЕЧЕТИ (ТАХИЯТ АЛЬ-МАСДЖИД)<sup class=\"fn\">667</sup>"],["n",[[667,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Для него приветствием мечети (тахият) является сам таваф, а затем молитва за макамом Ибрахима. См. \"аль-Кауа′ид ан-нурания\", 101, Ибн Теймии». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 114; «аль-Манасик», стр. 51. </b>"],["h3","<b>Сказал наш шейх аль-Альбани (да помилует его Аллах) после хадиса 1012</b><sup class=\"fn\">668</sup><b> в книге «ад-Да′ифа», 3/73-74: </b>"],["n",[[668,"В этом хадисе сказано: <b><i>«Приветствие Дома (Каабы) – это таваф». </i></b>Шейх постановил, что у этого хадиса нет основы."]]],["p","«Я не знаю, чтобы что-то из слов или действий пророка (да благословит его Аллах и приветствует) свидетельствовало в пользу этого хадиса. Но пришли общие тексты о необходимости молитвы перед тем, как сесть в мечети, и они также охватывают и Заповедную мечеть (аль-харам). Что касается слов о том, что приветствием этой мечети является обход вокруг Каабы (таваф), то это противоречит тем общим религиозным текстам, о которых я сказал. Эти слова можно принять только в том случае, если хадис будет достоверным, однако это невозможно. К тому же из опыта людей известно, что человек, входящий в Заповедную мечеть (аль-харам), не может каждый раз, как он входит, совершать таваф, если это происходит в период хаджа. Вся хвала Аллаху, Который даровал в этом вопросе простор! <b>«Он не сделал для вас никакого затруднения в религии»</b><sup class=\"fn\">669</sup>."],["n",[[669,"Сура «аль-Хадж», аят 78."]]]],[["p","Здесь следует обратить внимание на то, что это постановление касается того, кто не находится в состоянии ихрама. Что касается того, кто находится в состоянии ихрама, то согласно Сунне он должен начать с тавафа, а после него совершить молитву в два ракаата»."],["sep",""],["h2","ВОПРОС № 5: СЛОВА: «ПОСРЕДСТВОМ СВОЕГО ТАВАФА НА ЭТОЙ НЕДЕЛЕ Я НАМЕРЕВАЮСЬ ТО-ТО И ТО-ТО»."],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 114; «аль-Манасик», стр. 51. </b>"],["sep",""],["p","ВОПРОС № 6: КОГДА ЧЕЛОВЕК ПРИКАСАЕТСЯ К ЧЁРНОМУ КАМНЮ, ОН ПОДНИМАЕТ РУКИ ТАК ЖЕ, КАК ПОДНИМАЕТ ИХ ПЕРЕД ВСТУПЛЕНИЕМ В МОЛИТВУ<sup class=\"fn\">670</sup>"],["n",[[670,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Выдающийся учёный аль-Файруз Абади упомянул, что так поступают только невежды, несмотря на то, что так гласит мазхаб ханафитов. В книге \"аль-Хидая\" в их пользу аргументировали следующим хадисом: \"Не поднимают руки, кроме как в семи местах…\", и затем среди них упомянуто прикосновение к Чёрному камню. Однако этот хадис является слабым по всем его путям передачи. К тому же Ибн уль-Хумам в \"Фатх аль-Кадир\", 2/148, 153, упомянул, что вообще нет основы упоминанию Чёрного камня в этом хадисе. Вероятно, он перенял это от аз-Зейля′и в \"Насб ар-рая\", 2/38. Но с этим можно не согласиться, однако здесь не место для разъяснения этого вопроса». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 114; «аль-Манасик», стр. 51. </b>"],["sep",""],["h2","ВОПРОС № 7: НЕКОТОРЫЕ ЛЮДИ ИЗДАЮТ ГРОМКИЙ ЗВУК ПРИ ЦЕЛОВАНИИ ЧЁРНОГО КАМНЯ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 114; «аль-Манасик», стр. 51. </b>"],["sep",""],["p","ВОПРОС № 8: НЕКОТОРЫЕ ЛЮДИ СОЗДАЮТ СТОЛПОТВОРЕНИЕ, ЧТОБЫ ПОЦЕЛОВАТЬ ЧЁРНЫЙ КАМЕНЬ, А НЕКОТОРЫЕ ДАЖЕ НАМЕРЕННО ЗАКАНЧИВАЮТ МОЛИТВУ РАНЬШЕ ИМАМА ДЛЯ ЭТОГО"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 114; «аль-Манасик», стр. 51. </b>"],["sep",""],["h2","ВОПРОС № 9: НЕКОТОРЫЕ ЛЮДИ, ПРИКАСАЯСЬ К ЧЁРНОМУ КАМНЮ, ГОВОРЯТ: «О АЛЛАХ! С ВЕРОЙ В ТЕБЯ И ПОДТВЕРЖДАЯ ТВОЮ КНИГУ!»<sup class=\"fn\">671</sup>."],["n",[[671,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«В книге \"аль-Мудаввана\", 2/124, пришло, что имам Малик порицал людей, которые, подходя к Чёрному камню, говорят: \"С верой в Тебя…\". При этом эти слова передаются от ′Али и Ибн ′Умара по двум слабым цепочкам передачи. И не обольщайся словами аль-Хейсами, который сказал о хадисе Ибн ′Умара: \"Его передатчики являются передатчиками достоверных сборников\". Дело в том, что он перепутал одного передатчика с другим, как я разъяснил это в \"ас-Сильсиля\"». </i> Однако сказал шейх Машхур Абу ′Убейда: <i>«Шейх (аль-Альбани) отказался от мнения о том, что эти предания являются слабыми. Я слышал это от него лично, но в его книгах этого нет». </i>"]]]],[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 115; «аль-Манасик», стр. 51. </b>"],["sep",""],["p","ВОПРОС № 10: НЕКОТОРЫЕ ЛЮДИ, ПРИКАСАЯСЬ К ЧЁРНОМУ КАМНЮ, ГОВОРЯТ: «О АЛЛАХ! ПОИСТИНЕ, Я ПРОШУ ТВОЕЙ ЗАЩИТЫ ОТ ВЫСОКОМЕРИЯ И НУЖДЫ, А ТАКЖЕ ОТ СТЕПЕНЕЙ ПОЗОРА В БЛИЖНЕЙ ЖИЗНИ И В ПОСЛЕДНЕЙ ОБИТЕЛИ»<sup class=\"fn\">672</sup>."],["n",[[672,"Хадис, в котором приходит эта мольба, является выдуманным."]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 115; «аль-Манасик», стр. 51. </b>"],["sep",""],["h2","ВОПРОС № 11: НЕКОТОРЫЕ ЛЮДИ ВО ВРЕМЯ ОБХОДА ВОКРУГ КААБЫ ВОЗЛАГАЮТ ПРАВУЮ РУКУ НА ЛЕВУЮ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 115; «аль-Манасик», стр. 51. </b>"],["sep",""],["p","ВОПРОС № 12: НЕКОТОРЫЕ ЛЮДИ, ДОХОДЯ ДО ДВЕРЕЙ КААБЫ, ГОВОРЯТ: «О АЛЛАХ! ПОИСТИНЕ, ЭТОТ ДОМ – ТВОЙ ДОМ, И ЭТА ЗАПОВЕДНАЯ ТЕРРИТОРИЯ – ТВОЯ ЗАПОВЕДНАЯ ТЕРРИТОРИЯ, И ЭТО БЕЗОПАСНОЕ МЕСТО – ТВОЁ БЕЗОПАСНОЕ МЕСТО. И Я, СТОЯ ЗДЕСЬ, ПРИБЕГАЮ К ТЕБЕ ЗА ЗАЩИТОЙ ОТ ОГНЯ», И В ЭТОТ МОМЕНТ ПОКАЗЫВАЮТ НА СЛЕДЫ ИБРАХИМА (МАКАМУ ИБРАХИМ), МИР ЕМУ."],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 115; «аль-Манасик», стр. 51. </b>"],["sep",""],["p","ВОПРОС № 13: НЕКОТОРЫЕ ЛЮДИ ВОЗЛЕ ИРАКСКОГО УГЛА КААБЫ ПРОИЗНОСЯТ СЛЕДУЮЩУЮ МОЛЬБУ: «О АЛЛАХ! ПОИСТИНЕ, Я ПРОШУ ТВОЕЙ ЗАЩИТЫ ОТ СОМНЕНИЙ, ОТ МНОГОБОЖИЯ, ОТ РАСКОЛА, ОТ ЛИЦЕМЕРИЯ, ОТ ДУРНЫХ НРАВОВ И ОТ СКВЕРНОГО ИТОГА В ЖЁНАХ, ИМУЩЕСТВЕ И ДЕТЯХ»."],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 115; «аль-Манасик», стр. 52. </b>"],["sep",""],["p","ВОПРОС № 14: НЕКОТОРЫЕ ЛЮДИ ВОЗЛЕ МИЗАБА (ВОДОСТОК КААБЫ) ПРОИЗНОСЯТ СЛЕДУЮЩУЮ МОЛЬБУ: «О АЛЛАХ! УКРОЙ МЕНЯ В СВОЕЙ ТЕНИ В ТОТ ДЕНЬ, КОГДА НЕ БУДЕТ ИНОЙ ТЕНИ, КРОМЕ ТВОЕЙ ТЕНИ. И НАПОИ МЕНЯ ИЗ ЧАШИ НАШЕГО ГОСПОДИНА МУХАММАДА ТАКИМ ПИТЬЁМ, КОТОРОЕ ВО БЛАГО И НА ЗДОРОВЬЕ, И ПОСЛЕ КОТОРОГО Я НИКОГДА НЕ ИСПЫТАЮ ЖАЖДЫ, О ОБЛАДАТЕЛЬ ВЕЛИЧИЯ И ЩЕДРОСТИ!»."],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 116; «аль-Манасик», стр. 52. </b>"],["sep",""],["p","ВОПРОС № 15: НЕКОТОРЫЕ ЛЮДИ ВО ВРЕМЯ БЫСТРОЙ ХОДЬБЫ (РАМАЛЬ)<sup class=\"fn\">673</sup> ПРОИЗНОСЯТ СЛЕДУЮЩУЮ МОЛЬБУ: «О АЛЛАХ! СДЕЛАЙ ЭТОТ ХАДЖ БЛАГОЧЕСТИВЫМ И ВСЕ ГРЕХИ ПРОЩЁННЫМИ, И МОЁ УСЕРДИЕ ВОЗНАГРАЖДЁННЫМ, И ЧТОБЫ ЭТО СТАЛО ТОРГОВЛЕЙ, КОТОРАЯ НЕ ОКАЖЕТСЯ БЕЗУСПЕШНОЙ, О ВЕЛИКИЙ, О ПРОЩАЮЩИЙ»<sup class=\"fn\">674</sup>."],["n",[[673,"Рамаль – это быстрая ходьба с целью продемонстрировать физическую силу и выносливость. Таким образом мужчины совершают первые три круга во время обхода вокруг Каабы. На женщин это предписание не распространяется."],[674,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Ар-Рафи′и передал эту мольбу от пророка (да благословит его Аллах и приветствует), но у этого хадиса нет основы, как на это указал хафиз (Ибн Хаджар) в «ат-Тальхис», стр. 214, сказав: \"Я не нашёл такой хадис\"».</i>"]]]],[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 116; «аль-Манасик», стр. 52. </b>"],["sep",""],["p","ВОПРОС № 16: НЕКОТОРЫЕ ЛЮДИ ВО ВРЕМЯ ЧЕТЫРЁХ ПОСЛЕДНИХ КРУГОВ ТАВАФА ГОВОРЯТ: «ГОСПОДИ! ПРОСТИ И ПОМИЛУЙ, И ПРОЯВИ СНИСХОДИТЕЛЬНОСТЬ В ТОМ, О ЧЁМ ТЫ ЗНАЕШЬ! ПОИСТИНЕ, ТЫ – ВЕЛИЧАЙШИЙ И ШЕДРЕЙЩИЙ»<sup class=\"fn\">675</sup>."],["n",[[675,"Сказал шейх ислама Ибн Теймия в «Мансак», стр. 372: <i>«Во время тавафа человеку желательно поминать Всевышнего Аллаха и произносить те мольбы, которые узаконены в шариате. Если он будет читать Коран шепотом, то в этом нет греха. Но здесь нет какого-то установленного от пророка (да благословит его Аллах и приветствует) поминания (зикр). Он не велел произносить что-то конкретное, не произносил что-то конкретное сам и не обучал чему-то конкретному других. Напротив, в этот момент человек произносит любые мольбы, узаконенные шариатом. Многие люди упоминают определенные мольбы, которые следует произносить возле мизаба и других мест, но этому нет никакой основы. Пророк (да благословит его Аллах и приветствует), когда завершал свой таваф между двумя углами, читал аят: </i><b>\"Господь наш! Одари нас добром в этом мире и добром в Последней жизни и защити нас от мучений в Огне\". </b><i>(Сура «аль-Бакара», аят 201). Также он завершал этими словами и другие свои мольбы. И это поминание Аллаха не является обязательным по единогласному мнению имамов». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 116; «аль-Манасик», стр. 52. </b>"],["sep",""],["h2","ВОПРОС № 17: ЦЕЛОВАНИЕ ЙЕМЕНСКОГО УГЛА<sup class=\"fn\">676</sup>"],["n",[[676,"Как известно, Кааба имеет четыре угла. С южной стороны Каабы (со стороны Йемена) находятся угол, где находится Черный Камень, и йеменский угол Каабы. Другие два угла Каабы называют сирийскими (шамскими), так как они находятся со стороны Сирии (Шама). Угол, где находится Черный Камень, имеет два достоинства: во-первых, он построен на фундаменте пророка Ибрахима, а во-вторых, именно в нем находится Черный Камень. Что же касается йеменского угла, то его достоинство в том, что он также возведен на фундаменте пророка Ибрахима. Так как угол, где находится Черный Камень, имеет два достоинства, в исламской религии выделено два обряда, связанных с ним: прикосновение к нему и целование его. А йеменский угол имеет только одно достоинство, потому в исламской религии выделен лишь один обряд, связанный с ним: прикосновение. Человек, обходящий вокруг Каабы, не целует йеменский угол. Что же касается двух оставшихся (сирийских) углов Каабы, то к ним не прикасаются и их не целуют. А Аллах знает лучше! См. «Аль-Бахр уль-мухит ус-саджадж», 23/464."]]]],[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 116; «аль-Манасик», стр. 52. </b>"],["sep",""],["h2","ВОПРОС № 18: ЦЕЛОВАНИЕ И ПРИКОСНОВЕНИЕ К ДВУМ СИРИЙСКИМ (ШАМСКИМ) УГЛАМ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 117; «аль-Манасик», стр. 52. </b>"],["sep",""],["h2","ВОПРОС № 19: НЕКОТОРЫЕ ЛЮДИ ОБТИРАЮТСЯ О КААБУ И О МЕСТО СТОЯНИЯ ИБРАХИМА (МАКАМУ ИБРАХИМ)"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 117; «аль-Манасик», стр. 52. </b>"],["sep",""],["p","ВОПРОС № 20: НА ПРОТИВОПОЛОЖНОЙ СТОРОНЕ ОТ ДВЕРИ КААБЫ ЕСТЬ ВЫСОКАЯ ЧАСТЬ СТЕНЫ КААБЫ, И НЕКОТОРЫЕ НЕВЕЖЕСТВЕННЫЕ ЛЮДИ ДУМАЮТ, ЧТО ЕСЛИ ЧЕЛОВЕК СХВАТИТ ЭТО МЕСТО РУКОЙ, ТО ОН СХВАТИЛСЯ ЗА САМУЮ НАДЁЖНУЮ РУКОЯТЬ<sup class=\"fn\">677</sup>"],["n",[[677,"О которой говорится в Коране: <b>«Кто не верует в тагута</b> [лжебога]<b> и верует в Аллаха, тот ухватился за самую надежную рукоять, которая никогда не сломается».</b> (Сура «аль-Бакара», аят 256). Сказал Абу Шама в «аль-Ба′ис», стр. 69: <i>«Чтобы добраться до этого места, они готовы переносить тяжести и сложности. Люди даже лезут друг на друга для этого, и бывает так, что женщина залезает на мужчину». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 117; «аль-Манасик», стр. 52. </b>"],["sep",""],["p","ВОПРОС № 21: В ЦЕНТРЕ КААБЫ ЕСТЬ КРЮК, КОТОРОЙ ЛЮДИ НАЗВАЛИ «ПУПОМ ЗЕМЛИ». И ВОТ НЕКОТОРЫЕ ИЗ НИХ ОБНАЖАЮТ СВОЙ ПУПОК И ЛОЖАТСЯ НА ЭТО МЕСТО, ПРИКАСАЯСЬ СВОИМ ПУПКОМ К ЭТОМУ «ПУПУ ЗЕМЛИ»<sup class=\"fn\">678</sup>."],["n",[[678,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Ибн уль-Хумам упомянул это и предыдущее действия, сказав, что это – ложное новшество, у которого нет основы, и что так поступают только те, у кого нет разума, не говоря уже о наличии знаний». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 117; «аль-Манасик», стр. 52. </b>"],["sep",""],["p","ВОПРОС № 22: НЕКОТОРЫЕ ЛЮДИ НАМЕРЕННО СТРЕМЯТСЯ СОВЕРШИТЬ ТАВАФ ПОД ДОЖДЁМ, СЧИТАЯ, ЧТО СОВЕРШИВШЕМУ ТАВАФ ПОД ДОЖДЁМ БУДУТ ПРОЩЕНЫ ВСЕ ПРОШЛЫЕ ГРЕХИ<sup class=\"fn\">679</sup>"],["n",[[679,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Что касается хадиса: </i><b><i>\"Кто будет совершать таваф под дождём в течение недели, тому будут прощены все прошлые грехи\", </i></b><i>то у него нет основы, как об этом сказал аль-Бухари и другие (учёные)». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 118; «аль-Манасик», стр. 52. </b>"],["sep",""],["p","ВОПРОС № 23: НЕКОТОРЫЕ ЛЮДИ ИЩУТ БЛАГОДАТИ (БАРАКА) ОТ ДОЖДЯ, КОТОРЫЙ СТЕКАЕТ С КААБЫ ЧЕРЕЗ ВОДОСТОК, ИМЕНУЕМЫЙ «АР-РАХМА» (МИЛОСТЬ)"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 118; «аль-Манасик», стр. 53. </b>"],["sep",""],["h2","ВОПРОС № 24: ОТКАЗ ОТ ТАВАФА В ОДЕЖДЕ, НА КОТОРОЙ ЕСТЬ ГРЯЗЬ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 118; «аль-Манасик», стр. 53. </b>"],["sep",""]],[["p","ВОПРОС № 24: НЕКОТОРЫЕ ЛЮДИ ПЬЮТ ВОДУ ЗАМ-ЗАМ, А ЗАТЕМ ВЫЛИВАЮТ НЕДОПИТЫЕ ОСТАТКИ ОБРАТНО В КОЛОДЕЦ, ГОВОРЯ ПРИ ЭТОМ: «О АЛЛАХ! ПОИСТИНЕ, Я ПРОШУ У ТЕБЯ ШИРОКОГО УДЕЛА, ПОЛЕЗНОГО ЗНАНИЯ, ИСЦЕЛЕНИЯ ОТ ВСЯКОЙ БОЛЕЗНИ…»."],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 118; «аль-Манасик», стр. 53. </b>"],["sep",""],["h2","ВОПРОС № 25: НЕКОТОРЫЕ ЛЮДИ СОВЕРШАЮТ ПОЛНОЕ ОМОВЕНИЕ (ГУСЛЬ) ВОДОЙ ЗАМ-ЗАМ<sup class=\"fn\">680</sup>"],["n",[[680,"То есть, считая это желательным действием и частью религией. С этой стороны это действие становится новшеством. Сказал Ибн Теймия в «Мансак», стр. 388: <i>«Желательно напиться водой зам-зам и во время её питья произносить те мольбы, узаконенные шариатом, какие человек сам пожелает. Но не является желательным совершать полное омовение (гусль) этой водой». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 118; «аль-Манасик», стр. 53. </b>"],["sep",""],["p","ВОПРОС № 26: НЕКОТОРЫЕ ЛЮДИ ОБТИРАЮТ ВОДОЙ ЗАМ-ЗАМ СВОИ БОРОДЫ, ОКУНАЮТ В НЕЁ МОНЕТЫ И ОДЕЖДЫ, СЧИТАЯ, ЧТО ТАК НА НИХ ПЕРЕХОДИТ БЛАГОДАТЬ (БАРАКА)"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 119; «аль-Манасик», стр. 53. </b>"],["sep",""],["p","ВОПРОС № 27: В НЕКОТОРЫХ КНИГАХ ПО ФИКХУ СКАЗАНО, ЧТО ВО ВРЕМЯ ПИТЬЯ ЗАМ-ЗАМА НУЖНО СДЕЛАТЬ НЕСКОЛЬКО ПЕРЕДЫШЕК И ВО ВРЕМЯ КАЖДОЙ ПЕРЕДЫШКИ НУЖНО ПОДНЯТЬ ГЛАЗА И ПОСМОТРЕТЬ НА КААБУ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 119; «аль-Манасик», стр. 53. </b>"],["sep",""],["h2","ГЛАВА № 4 – НОВШЕСТВА, СВЯЗАННЫЕ С РИТУАЛЬНЫМ ПРОХОДОМ (СА′Ю) МЕЖДУ ХОЛМАМИ САФА И МАРВА"],["p","ВОПРОС № 1: СОВЕРШЕНИЕ МАЛОГО ОМОВЕНИЯ (ВУДУ) ДЛЯ ПРОХОДА (СА′Ю) МЕЖДУ САФОЙ И МАРВОЙ С УБЕЖДЕНИЕМ О ТОМ, ЧТО СДЕЛАВШИЙ ТАК ЗА КАЖДЫЙ ШАГ БУДЕТ ВОЗВЫШЕН НА СЕМЬДЕСЯТ ТЫСЯЧ СТЕПЕНЕЙ<sup class=\"fn\">681</sup>"],["n",[[681,"В совершении омовения (вуду) для са′ю между Сафой и Марвой нет ничего греховного. Шейх (да помилует его Аллах) имеет в виду, что новшеством являются убеждения о награде, о которой ничего не говорится в достоверных религиозных текстах. То же самое касается тех мольб, которые он упомянул выше. В обращении к Аллаху нет ничего греховного, но новшеством является то, что человек думает, что именно в этом месте нужно произнести именно эту мольбу, считая, что этим обязывает его религия, хотя в религиозных текстах нет ничего подобного."]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 119; «аль-Манасик», стр. 53. </b>"],["sep",""],["h2","ВОПРОС № 2: ВОСХОЖДЕНИЕ НА ХОЛМ САФА НАСТОЛЬКО, ЧТО ЧЕЛОВЕК УЖЕ ПРИЖИМАЕТСЯ К СТЕНЕ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 119; «аль-Манасик», стр. 63. </b>"],["sep",""],["p","ВОПРОС № 3: НЕКОТОРЫЕ ЛЮДИ, СПУСКАЯСЬ С ХОЛМА САФА, ГОВОРЯТ: «О АЛЛАХ! ИСПОЛЬЗУЙ МЕНЯ В СООТВЕТСТВИИ С СУННОЙ ТВОЕГО ПРОРОКА, УМЕРТВИ МЕНЯ НА ЕГО РЕЛИГИИ И ЗАЩИТИ МЕНЯ ОТ СМУТ, ВВОДЯЩИХ В ЗАБЛУЖДЕНИЕ, ПО МИЛОСТИ ТВОЕЙ, О МИЛОСТИВЕЙШИЙ ИЗ МИЛОСТИВЫХ»."]],[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 119; «аль-Манасик», стр. 53. </b>"],["sep",""],["p","ВОПРОС № 4: НЕКОТОРЫЕ ЛЮДИ ВО ВРЕМЯ СА′Ю ГОВОРЯТ: «ГОСПОДИ! ПРОСТИ И ПОМИЛУЙ, И ПРОЯВИ СНИСХОДИТЕЛЬНОСТЬ В ТОМ, О ЧЁМ ТЫ ЗНАЕШЬ! ПОИСТИНЕ, ТЫ – ВЕЛИЧАЙШИЙ И ШЕДРЕЙЩИЙ! О АЛЛАХ! СДЕЛАЙ ЭТОТ ХАДЖ (ИЛИ: ′УМРУ) БЛАГОЧЕСТИВЫМ И ПРОСТИ ГРЕХИ!», И ТАК ДАЛЕЕ ДО КОНЦА ИХ ДЛИННОЙ МОЛЬБЫ<sup class=\"fn\">682</sup>"],["n",[[682,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Достоверно передано, что Ибн Мас′уд и Ибн ′Умар говорили: \"Господи! Прости и помилуй! Поистине, Ты – Величайший и Щедрейший!\". Это передал аль-Бейхакы. Также эти слова переданы от пророка (да благословит его Аллах и приветствует), но хадис не является достоверным». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 120; «аль-Манасик», стр. 53. </b>"],["sep",""],["h2","ВОПРОС № 5: НЕКОТОРЫЕ ЛЮДИ ПРОХОДЯТ МЕЖДУ САФОЙ И МАРВОЙ ЧЕТЫРНАДЦАТЬ РАЗ ТАК, ЧТО ИХ ОБРЯД ЗАКАНЧИВАЕТСЯ НА САФЕ<sup class=\"fn\">683</sup>"],["n",[[683,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«В соответствии с Сунной проход между ними совершается только семь раз и обряд завершается на Марве».  </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 120; «аль-Манасик», стр. 54. </b>"],["sep",""],["h2","ВОПРОС № 6: МНОКРАТНОЕ ПОВТОРЕНИЕ СА′Ю ВО ВРЕМЯ ХАДЖА ИЛИ ′УМРЫ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 120; «аль-Манасик», стр. 54. </b>"],["sep",""],["h2","ВОПРОС № 7: СОВЕРШЕНИЕ МОЛИТВЫ В ДВА РАКААТА ПОСЛЕ ЗАВЕРШЕНИЯ СА′Ю<sup class=\"fn\">684</sup>"],["n",[[684,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Многие учёные назвали эти два ракаата желательными, проведя аналогию с двумя ракаатами, совершаемыми после тавафа. А Ибн уль-Хумам в «аль-Фатх», 2/156-157, сказал следующее:</i> <i>«Нет нужды в этой аналогии, так как на эту тему есть хадис. Аль-Мутталиб ибн Аби Уада′а рассказывал: \"Я видел, что посланник Аллаха (да благословит его Аллах и приветствует) завершил своё са′ю и… совершил молитву в два ракаата на краю того места, где совершают таваф, причём между ним и теми, кто совершает таваф, не было никого\". Передали Ахмад и Ибн Маджа». </i> <i>Я скажу: это – удивительная оплошность со стороны такого выдающегося учёного. В его источниках по ошибке было написано слово «са′и-хи» </i>(<span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">سعيه</span>) <i>(после своего са’ю), хотя правильным является то, что в хадисе сказано: «саб′ихи» </i>(<span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">سبعه</span>) <i>(после семи кругов тавафа), как это пришло у Ибн Маджа, 2958. И похожее слово пришло в «Муснаде» (Ахмада). А в другой версии у Ахмада сказано: \"Он обошёл вокруг Каабы семь раз, а затем совершил молитву в два ракаата напротив Каабы\". К тому же этот хадис в своей основе не является достоверным со стороны цепочки передатчиков. В ней есть путаница (идтыраб) и неизвестность (джахаля), что я разъяснил в книге \"ад-Да′ифа\", 928». </i>"]]]],[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 121; «аль-Манасик», стр. 54. </b>"],["h3","<b>Сказал наш шейх, да помилует его Всевышний Аллах, в «ад-Да′ифа», 2/328, после хадиса № 928:</b>"],["p","«Выдающийся учёный Ибн уль-Хумам в «Фатх аль-Кадир» упомянул эту версию<sup class=\"fn\">685</sup>, но в его источниках пришло искажение. Вместо слова «саб′и-хи» (после семи кругов тавафа) у него сказано: «са′и-хи» (после своего са′ю). Затем он аргументировал этой версией в пользу того, что желательно совершить молитву в два ракаата после са′ю. Но это является новшеством, внесённым в религию и не имеющим основы в Сунне, на что указали многие имамы, в числе которых Абу Шама и другие»."],["n",[[685,"То есть хадис, в котором сказано: <i>«Я видел, как посланник Аллаха (да благословит его Аллах и приветствует) завершил семь кругов тавафа, затем встал напротив угла Каабы и совершил два ракаата». </i>"]]],["sep",""],["p","ВОПРОС № 8: НЕКОТОРЫЕ ЛЮДИ ПРОДОЛЖАЮТ ПРОХОД (СА′Ю) МЕЖДУ САФОЙ И МАРВОЙ ДАЖЕ ТОГДА, КОГДА НАЧАЛАСЬ МОЛИТВА. ИЗ-ЗА ЭТОГО ОНИ ПРОПУСКАЮТ КОЛЛЕКТИВНУЮ МОЛИТВУ."],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 121; «аль-Манасик», стр. 54. </b>"],["sep",""],["p","ВОПРОС № 9: НЕКОТОРЫЕ ЛЮДИ ПРИДЕРЖИВАЮТСЯ ОПРЕДЕЛЁННЫХ МОЛЬБ, (НЕ ПРИШЕДШИХ В СУННЕ). НАПРИМЕР, КОГДА ОНИ ПРИХОДЯТ В (ДОЛИНУ) МИНА, ОНИ ГОВОРЯТ: «О АЛЛАХ! ЭТО – МИНА! ДАРУЙ ЖЕ МНЕ ТО, ЧТО ТЫ ДАРОВАЛ СВОИМ ПРИБЛИЖЁННЫМ И ПОКОРНЫМ РАБАМ!». А КОГДА ОНИ ПОКИДАЮТ МИНУ, ОНИ ГОВОРЯТ: «О АЛЛАХ! СДЕЛАЙ ЭТО МОИМ САМЫМ ЛУЧШИМ УХОДОМ…» И ТАК ДАЛЕЕ. ЭТИ МОЛЬБЫ УПОМЯНУЛ АВТОР КНИГИ «АЛЬ-ИХЬЯ»"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 121; «аль-Манасик», стр. 54. </b>"],["sep",""],["h2","ГЛАВА № 5 – НОВШЕСТВА, СВЯЗАННЫЕ С НАХОЖДЕНИЕМ НА ′АРАФАТЕ"],["p","ВОПРОС № 1: НЕКОТОРЫЕ ЛЮДИ НА КОРОТКОЕ ВРЕМЯ ПРИХОДЯТ НА ′АРАФАТ В ВОСЬМОЙ ДЕНЬ ЗУЛЬ-ХИДЖЖИ, ДЕЛАЯ ЭТО НА ВСЯКИЙ СЛУЧАЙ, ТАК КАК ВДРУГ ТЕ, КТО ЗАНИМАЛИСЬ ОПРЕДЕЛЕНИЕМ НАЧАЛА МЕСЯЦА, ОШИБЛИСЬ<sup class=\"fn\">686</sup>"],["n",[[686,"То есть эти люди мыслят так: «Вдруг сегодня не 8-ое число, а 9-ое, но просто люди ошиблись в определении начала месяца. Лучше я пойду на ′Арафат на всякий случай, \"подальше от греха\"». Здесь в примечаниях шейх аль-Альбани сказал: <i>«Это посчитал хорошим поступком автор книги «аль-Ихья» (то есть аль-Газали) и сказал: \"Это – благоразумие и осторожность\". Удивительно слышать такие вещи от такого знатока фикха. Если бы это на самом деле было хорошим поступком, то его совершал бы пророк (да благословит его Аллах и приветствует), который был самым богобоязненным из людей. </i> <i>Сказал шейх ислама (Ибн Теймия) в «аль-Маджму′», 2/374: \"Соблюдение осторожности – это хорошее дело, пока это не противоречит известной Сунне. А если это противоречит известной Сунне, то такая осторожность будет ошибочной\"». </i>"]]]],[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 122; «аль-Манасик», стр. 54. </b>"],["sep",""],["h2","ВОПРОС № 2: РАЗЖИГАНИЕ МНОГОЧИСЛЕННЫХ СВЕЧЕЙ В МИНЕ В НОЧЬ ПЕРЕД ОТПРАВЛЕНИЕМ НА ′АРАФАТ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 122; «аль-Манасик», стр. 54. </b>"],["sep",""],["p","ВОПРОС № 3: НЕКОТОРЫЕ ЛЮДИ В НОЧЬ ПЕРЕД ОТПРАВЛЕНИЕМ НА ′АРАФАТ ПРОИЗНОСЯТ СЛЕДУЮЩУЮ МОЛЬБУ ТЫСЯЧУ РАЗ: «ПРЕЧИСТ ТОТ, ЧЕЙ ТРОН НАД НЕБЕСАМИ! ПРЕЧИСТ ТОТ, ЧЬИ СЛЕДЫ НА ЗЕМЛЕ! ПРЕЧИСТ ТОТ, ЧЕЙ ПУТЬ В МОРЕ!», И ТАК ДАЛЕЕ<sup class=\"fn\">687</sup>"],["n",[[687,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Об этом пришёл хадис, но его цепочка передатчиков является слабой. А Ибн уль-Джаузи вообще привёл его среди выдуманных хадисов и сказал: \"Недостоверный\". Его опроверг ас-Суюты в «аль-Ляали», 1/120, но из слов ас-Суюты понимается, что он считал этот хадис слабым». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 122; «аль-Манасик», стр. 54. </b>"],["sep",""],["h2","ВОПРОС № 4: ОТПРАВЛЕНИЕ В ВОСЬМОЙ ДЕНЬ ЗУЛЬ-ХИДЖЖИ ИЗ МЕККИ СРАЗУ НА ′АРАФАТ (БЕЗ НОЧЁВКИ В МИНЕ)<sup class=\"fn\">688</sup>"],["n",[[688,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Сунна и даже обязательное действие (уаджиб) – это проведение ночи перед ′Арафатом в Мине. Многие люди стали беспечно относиться к этой Сунне и им в этом помогают руководители паломнических групп, которых не заботит следование за пророком (да благословит его Аллах и приветствует) при совершении хаджа. Также они находят некоторых знатоков религии, которые облегчают им легкомысленное отношение к этому делу. Например, аль-Газали сказал: \"Ночёвка в Мине – это просто остановка на привал на ночь. Она не имеет отношения к обрядам хаджа\"».</i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 123; «аль-Манасик», стр. 54. </b>"],["sep",""],["h2","ВОПРОС № 5: ОТПРАВЛЕНИЕ ИЗ МИНЫ В ′АРАФАТ НОЧЬЮ<sup class=\"fn\">689</sup>"],["n",[[689,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«В соответствии с Сунной покидать Мину нужно после восхода солнца в день ′Арафата (девятое число)». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 123; «аль-Манасик», стр. 54. </b>"],["sep",""],["h2","ВОПРОС № 6: РАЗЖИГАНИЕ ОГНЕЙ И СВЕЧЕЙ НА ГОРЕ ′АРАФАТ В НОЧЬ ПЕРЕД ДНЁМ ′АРАФАТА"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 123; «аль-Манасик», стр. 54. </b>"],["sep",""],["h2","ВОПРОС № 7: СОВЕРШЕНИЕ ПОЛНОГО ОМОВЕНИЯ (ГУСЛЬ) ДЛЯ ДНЯ ′АРАФАТА<sup class=\"fn\">690</sup>"],["n",[[690,"В этом вопросе ни в коем случае не следует порицать тех, кто совершает полное омовение (гусль) перед тем, как отправиться на ′Арафат. Потому что относительно желательности этого были единогласны все четыре мазхаба и из-за сообщений, переданных на эту тему. Когда ′Али (да будет доволен им Аллах) спросили о полном омовении (гусль), он ответил: <i>«(Оно совершается) в пятницу, в день ′Арафата, в день жертвоприношения и в день разговения (после рамадана)». </i>Передали аш-Шафи′и в «аль-Умм», 8/391; аль-Бейхакы, 6343. И сам шейх аль-Альбани назвал цепочку передатчиков этого сообщения достоверной. См. «Ируа аль-галиль», 1/177. Также Нафи′ передал, что Ибн ′Умар (да будет доволен Аллах им и его отцом) совершал полное омовение (гусль) перед тем, как отправиться на ′Арафат. Передал Малик в «аль-Муватта», 1/322. А Аллах знает лучше!"]]]],[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 123; «аль-Манасик», стр. 54. </b>"],["sep",""],["p","ВОПРОС № 8: НЕКОТОРЫЕ ЛЮДИ, КОГДА ПРИБЛИЖАЮТСЯ К ′АРАФАТУ И ВИДЯТ ГОРУ АР-РАХМА, ГОВОРЯТ: «ПРЕЧИСТ АЛЛАХ! ХВАЛА АЛЛАХУ! НЕТ ИСТИННОГО БОГА, КРОМЕ АЛЛАХА! ПРЕВЕЛИК АЛЛАХ!»."],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 124; «аль-Манасик», стр. 55. </b>"],["sep",""],["p","ВОПРОС № 9: ПРЕДНАМЕРЕННЫЙ ПРИХОД НА ′АРАФАТ ДО НАСТУПЛЕНИЯ ВРЕМЕНИ НАХОЖДЕНИЯ ТАМ, КОТОРОЕ НАСТУПАЕТ В ПОЛДЕНЬ ДНЯ ′АРАФАТА"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 124; «аль-Манасик», стр. 55. </b>"],["sep",""],["p","ВОПРОС № 10: НЕКОТОРЫЕ ЛЮДИ, НАХОДЯСЬ НА ′АРАФАТЕ, СТО РАЗ ПРОИЗНОСЯТ: «ЛЯ ИЛЯХА ИЛЛЯ ЛЛАХ», ЗАТЕМ СТО РАЗ ЧИТАЮТ СУРУ «АЛЬ-ИХЛЯС» (№ 112), ЗАТЕМ СТО РАЗ ПРОСЯТ БЛАГОСЛОВЕНИЯ ДЛЯ ПРОРОКА (ДА БЛАГОСЛОВИТ ЕГО АЛЛАХ И ПРИВЕТСТВУЕТ) И В КОНЦЕ ДОБАВЛЯЮТ: «И БЛАГОСЛОВИ НАС ВМЕСТЕ С НИМ»."],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 124; «аль-Манасик», стр. 55. </b>"],["sep",""],["h2","ВОПРОС № 11: НЕКОТОРЫЕ ЛЮДИ, НАХОДЯСЬ НА ′АРАФАТЕ, МОЛЧАТ И НЕ ОБРАЩАЮТСЯ С МОЛЬБАМИ К АЛЛАХУ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 124; «аль-Манасик», стр. 55. </b>"],["sep",""],["h2","ВОПРОС № 12: ВОСХОЖДЕНИЕ НА ГОРУ АР-РАХМА НА ′АРАФАТЕ<sup class=\"fn\">691</sup>"],["n",[[691,"Сказал Ибн Теймия: <i>«Учёные единогласны в том, что не является узаконенным в шариате восхождение на гору ар-Рахма». </i>См. «аль-Ихтиярат», 69."]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 124; «аль-Манасик», стр. 55. </b>"],["sep",""],["p","ВОПРОС № 13: НЕКОТОРЫЕ ЛЮДИ ВХОДЯТ ПОД КУПОЛ НА ГОРЕ АР-РАХМА, СОВЕРШАЮТ ТАМ МОЛИТВУ И СОВЕРШАЮТ ВОКРУГ НЕГО ОБХОД, ПОДОБНО ОБХОДУ ВОКРУГ КААБЫ. ОНИ НАЗЫВАЮТ ЭТО МЕСТО «КУПОЛОМ АДАМА»."],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 125; «аль-Манасик», стр. 55. </b>"],["sep",""],["p","ВОПРОС № 14: НЕКОТОРЫЕ ЛЮДИ ДУМАЮТ, ЧТО ВО ВТОРОНУ ПОЛОВИНУ ДНЯ ′АРАФАТ ВСЕВЫШНИЙ НИСХОДИТ НА ВЕРБЛЮДЕ ПЕПЕЛЬНОГО ЦВЕТА И ПОЖИМАЕТ РУКИ ВСАДНИКАМ, И ОБНИМАЕТ ПЕШИХ<sup class=\"fn\">692</sup>"],["n",[[692,"Ибн Теймия (да помилует его Аллах) упомянул, что кто-то даже передал об этом хадис. Затем Ибн Теймия сказал: <i>«И это относится к примерам величайшей лжи на Аллаха и Его посланника (да благословит его Аллах и приветствует). А тот, кто произнёс эти слова, возвёл на Аллаха величайшую клевету». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 125; «аль-Манасик», стр. 55. </b>"],["sep",""],["h2","ВОПРОС № 15: ИМАМ НА ′АРАФАТЕ ПРОИЗНОСИТ ДВЕ ПРОПОВЕДИ, САДЯСЬ МЕЖДУ НИМИ, КАК ЭТО ДЕЛАЕТСЯ ВО ВРЕМЯ ПЯТНИЧНОЙ ПРОПОВЕДИ<sup class=\"fn\">693</sup>"],["n",[[693,"Учёные разногласили в этом вопросе. Некоторые сказали, что в день ′Арафата произносится две проповеди, которые разделяются коротким сидением. Этого мнения придерживалось большинство учёных, среди которых ханафиты, маликиты и шафи′иты. Они провели аналогию с пятничной проповедью. Другие сказала, что в день ′Арафата произносится только одна неразделимая проповедь. Это мнение ханбалитов. Также это мнение выбрали Ибн уль-Каййим и Ибн ′Усеймин. Они опирались на то, что в хадисе Джабира (да будет доволен им Аллах), где приходит описание хаджа пророка (да благословит его Аллах и приветствует), пришло указание на одну целую проповедь и ничего не сказано о том, что проповедей было две. Этот хадис передал Муслим, 1218. А Аллах знает лучше!"]]]],[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 125; «аль-Манасик», стр. 55. </b>"],["sep",""],["h2","ВОПРОС № 16: СОВЕРШЕНИЕ ОБЕДЕННОЙ (ЗУХР) И ПОСЛЕОБЕДЕННОЙ (′АСР) МОЛИТВ ПЕРЕД ПРОПОВЕДЬЮ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 125; «аль-Манасик», стр. 55. </b>"],["sep",""],["p","ВОПРОС № 17: ПРОИЗНЕСЕНИЕ АЗАНА НА ОБЕДЕННУЮ (ЗУХР) И ПОСЛЕОБЕДЕННУЮ (′АСР) МОЛИТВЫ НА ′АРАФАТЕ ЕЩЁ ДО ТОГО, КАК ЗАКОНЧИТСЯ ПРОИЗНЕСЕНИЕ ПРОПОВЕДИ<sup class=\"fn\">694</sup>"],["n",[[694,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«В соответствии с Сунной азан нужно начинать после завершения проповеди». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 126; «аль-Манасик», стр. 55. </b>"],["sep",""],["p","ВОПРОС № 18: ПОСЛЕ ЗАВЕРШЕНИЯ МОЛИТВЫ НА ′АРАФАТЕ ИМАМ ОБРАЩАЕТСЯ К ЖИТЕЛЯМ МЕККИ: «А ВЫ СОВЕРШИТЕ МОЛИТВУ ПОЛНОСТЬЮ! МЫ ЖЕ ЯВЛЯЕМСЯ ПУТНИКАМИ (И ПОЭТОМУ СОКРАЩАЕМ)»<sup class=\"fn\">695</sup>."],["n",[[695,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Об этом сказано во многих ханафитских книгах. Они говорят, что имам на ′Арафате обязан произнести эти слова, если он является путником. Например, об этом сказано в «Тухфат аль-фукаха», 1/2/876. </i> <i>Шейх ислама Ибн Теймия сказал в «аль-Маджму′», 2/378:</i> <i>«Жители Мекки и жители других местностей – все они сокращают молитву. Также они объединяют две молитвы на ′Арафате, в Муздалифе и в Мине. Именно так делали жители Мекки, следуя за пророком (да благословит его Аллах и приветствует), на ′Арафате, в Муздалифе и в Мине. Точно так же они поступали за Абу Бакром и ′Умаром (да будет доволен ими Аллах). Ни пророк (да благословит его Аллах и приветствует), ни его халифы никогда не велели жителям Мекки совершать молитву полностью. Ни на ′Арафате, ни в Муздалифе, ни в Мине они не говорили: \"</i>А<i> вы совершите молитву полностью! Мы же являемся путниками\". А если кто-то передаёт от них такое, то он ошибся!». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 126; «аль-Манасик», стр. 55. </b>"],["sep",""],["h2","ВОПРОС № 19: СОВЕРШЕНИЕ ДОПОЛНИТЕЛЬНОЙ МОЛИТВЫ МЕЖДУ ОБЕДЕННОЙ (ЗУХР) И ПОСЛЕОБЕДЕННОЙ (′АСР) МОЛИТВАМИ НА ′АРАФАТЕ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 126; «аль-Манасик», стр. 55. </b>"],["sep",""],["p","ВОПРОС № 20: НАЗНАЧЕНИЕ ОПРЕДЕЛЕННОГО ПОМИНАНИЯ (ЗИКР) ИЛИ ОПРЕДЕЛЕННОЙ МОЛЬБЫ (ДУ′А) ДЛЯ ′АРАФАТА. КАК, НАПРИМЕР, АВТОР КНИГИ «АЛЬ-ИХЬЯ» ПРИВЁЛ ТАКУЮ МОЛЬБУ, НАЗВАВ ЕЁ МОЛЬБОЙ ХИДРА (МИР ЕМУ). ОНА НАЧИНАЕТСЯ СО СЛОВ: «О ТОТ, КОГО ОДНО ДЕЛО НЕ ОТВЛЕКАЕТ ОТ ДРУГОГО!». ЕСТЬ И ДРУГИЕ ТАКИЕ МОЛЬБЫ. НЕКОТОРЫЕ ИЗ НИХ ЗАНИМАЮТ БОЛЕЕ ШЕСТИ СТРАНИЦ, ЕСЛИ ИХ ЗАПИСАТЬ<sup class=\"fn\">696</sup>"],["n",[[696,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Шейх ислама (Ибн Теймия) сказал в «аль-Маджму′», 2/380: </i> <i>«Пророк (да благословит его Аллах и приветствует) не выделил для ′Арафата какую-то определенную мольбу или зикр. Напротив, человек может произносить любые мольбы, узаконенные шариатом. Также он произносит: «Аллаху акбар» и «Ля иляха илля Ллах», и поминает Всевышнего Аллаха, пока не зайдёт солнце». </i> <i>Я (аль-Альбани) скажу: также ему желательно произносить тальбию». </i>"]]]],[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 126; «аль-Манасик», стр. 56. </b>"],["sep",""],["h2","ВОПРОС № 21: НЕКОТОРЫЕ ЛЮДИ ПОКИДАЮТ ′АРАФАТ ДО ЗАХОДА СОЛНЦА"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 127; «аль-Манасик», стр. 56. </b>"],["sep",""],["p","ВОПРОС № 22: НЕКОТОРЫЕ НЕВЕЖЕСТВЕННЫЕ ЛЮДИ ГОВОРЯТ, ЧТО ЕСЛИ НАХОЖДЕНИЕ НА ′АРАФАТЕ СОВПАДАЕТ С ПЯТНИЧНЫМ ДНЁМ, ТО ЭТО РАВНО ПО НАГРАДЕ СЕМИДЕСЯТИ ДВУМ ХАДЖАМ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 127; «аль-Манасик», стр. 56. </b>"],["sep",""],["p","ВОПРОС № 23: ТО, ЧТО ИМЕНУЮТ ТЕРМИНОМ «ТА′РИФ». НЕКОТОРЫЕ ЛЮДИ НАМЕРЕННО СОБИРАЮТСЯ ВО ВТОРОЙ ПОЛОВИНЕ ДНЯ ′АРАФАТА В МЕЧЕТЯХ ИЛИ В КАКИХ-ТО МЕСТАХ ЗА ПРЕДЕЛАМИ НАСЕЛЕННОГО ПУНКТА, А ЗАТЕМ ОБРАЩАЮТСЯ К АЛЛАХУ С МОЛЬБАМИ, ГРОМКО ПОМИНАЮТ АЛЛАХА, ПРОИЗНОСЯТ ПРОПОВЕДИ И СТИХОТВОРЕНИЯ, ПОДРАЖАЯ ТЕМ, КТО НАХОДИТСЯ НА ′АРАФАТЕ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 128; «аль-Манасик», стр. 56. </b>"],["sep",""],["h2","ГЛАВА № 6 – НОВШЕСТВА, СВЯЗАННЫЕ С НАХОЖДЕНИЕМ В МУЗДАЛИФЕ"],["h2","ВОПРОС № 1: СПЕШКА ВО ВРЕМЯ ОТПРАВЛЕНИЯ ИЗ ′АРАФАТА В МУЗДАЛИФУ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 128; «аль-Манасик», стр. 56. </b>"],["sep",""],["h2","ВОПРОС № 2: СОВЕРШЕНИЕ ПОЛНОГО ОМОВЕНИЯ ПЕРЕД НОЧЁВКОЙ В МУЗДАЛИФЕ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 129; «аль-Манасик», стр. 56. </b>"],["sep",""],["p","ВОПРОС № 3: НЕКОТОРЫЕ ГОВОРЯТ, ЧТО ВСАДНИКУ ЖЕЛАТЕЛЬНО СПЕШИТЬСЯ И ВОЙТИ В МУЗДАЛИФУ ПЕШКОМ ИЗ УВАЖЕНИЯ К ЗАПОВЕДНОЙ ТЕРРИТОРИИ<sup class=\"fn\">697</sup>"],["n",[[697,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Это назвал желательным аль-Газали в книге «Ихья». Но если бы это было желательным, так поступил бы посланник Аллаха (да благословит его Аллах и приветствует). Однако мы уже приводили, что он прибыл в Муздалифу верхом, и что он, совершив утреннюю молитву, сел на свою верблюдицу и пришёл на Заповедную территорию». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 129; «аль-Манасик», стр. 56. </b>"],["sep",""],["p","ВОПРОС № 4: НЕКОТОРЫЕ, ДОСТИГАЯ МУЗДАЛИФЫ, СЧИТАЮТ ЖЕЛАТЕЛЬНЫМ ПРОИЗНЕСЕНИЕ КОНКРЕТНОЙ МОЛЬБЫ: «О АЛЛАХ! ПОИСТИНЕ, ЭТО – МУЗДАЛИФА. ЗДЕСЬ СОБРАЛИСЬ РАЗНЫЕ ЯЗЫКИ. МЫ ПРОСИМ ТЕБЯ ОБ ИСПОЛНЕНИИ НУЖД…», И ТАК ДАЛЕЕ. ЭТА МОЛЬБА ПРИВЕДЕНА В КНИГЕ «АЛЬ-ИХЬЯ»."],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 129; «аль-Манасик», стр. 56. </b>"],["sep",""],["p","ВОПРОС № 5: НЕКОТОРЫЕ ЛЮДИ, ПРИБЫВАЯ В МУЗДАЛИФУ, НЕ ТОРОПЯТСЯ СОВЕРШИТЬ ВЕЧЕРНЮЮ МОЛИТВУ (МАГРИБ), А ВМЕСТО ЭТОГО ЗАНИМАЮТСЯ СОБИРАНИЕМ КАМНЕЙ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 129; «аль-Манасик», стр. 56. </b>"],["sep",""],["p","ВОПРОС № 6: СОВЕРШЕНИЕ ДОПОЛНИТЕЛЬНОЙ МОЛИТВЫ МЕЖДУ ВЕЧЕРНЕЙ (МАГРИБ) И НОЧНОЙ (′ИША) МОЛИТВАМИ. ИЛИ ЖЕ НЕКОТОРЫЕ ПЕРЕНОСЯТ ЭТУ МОЛИТВУ И СОВЕРШАЮТ ЕЁ ВМЕСТЕ С СУННОЙ НОЧНОЙ МОЛИТВЫ (′ИША) И ВМЕСТЕ С МОЛИТВОЙ ВИТР. НА ТАКОЙ СПОСОБ УКАЗАЛ АЛЬ-ГАЗАЛИ"]],[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 129; «аль-Манасик», стр. 57. </b>"],["sep",""],["h2","ВОПРОС № 7: УВЕЛИЧЕНИЕ КОЛИЧЕСТВА ОГНЕЙ В НОЧЬ ПЕРЕД ПРАЗДНИКОМ ЖЕРТВОПРИНОШЕНИЯ И В МУЗДАЛИФЕ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 129; «аль-Манасик», стр. 57; «ас-Самар аль-мустатаб», 1/600. </b>"],["sep",""],["h2","ВОПРОС № 8: ПРОВЕДЕНИЕ НОЧИ ПЕРЕД ПРАЗДНИКОМ ЖЕРТВОПРИНОШЕНИЯ В ПОКЛОНЕНИИ<sup class=\"fn\">698</sup>"],["n",[[698,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Это посчитал желательным аль-Газали. Он сказал, что проведение этой ночи в поклонении – это одно из лучших благих дел. Но мы уже приводили, что пророк (да благословит его Аллах и приветствует) в эту ночь спал до появления зари, а лучший путь – это путь Мухаммада. Также мы приводили слова Ибн уль-Каййима на эту тему». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 130; «аль-Манасик», стр. 57.</b>"],["sep",""],["h2","ВОПРОС № 9: ОСТАНОВКА В МУЗДАЛИФЕ БЕЗ ПРОВЕДЕНИЯ В НЕЙ НОЧИ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 130; «аль-Манасик», стр. 57.</b>"],["sep",""],["p","ВОПРОС № 10: НЕКОТОРЫЕ, ДОХОДЯ ДО ЗАПОВЕДНОЙ ТЕРРИТОРИИ (АЛЬ-МАШ′АР АЛЬ-ХАРАМ), СЧИТАЮТ ЖЕЛАТЕЛЬНЫМ ПРОИЗНЕСЕНИЕ КОНКРЕТНОЙ МОЛЬБЫ: «О АЛЛАХ! ПОСРЕДСТВОМ ПРАВА ЗАПОВЕДНОЙ ТЕРРИТОРИИ И ЗАПОВЕДНОГО ДОМА, И ЗАПОВЕДНОГО МЕСЯЦА, А ТАКЖЕ УГЛОВ КААБЫ И МАКАМА, ДОВЕДИ ДО ДУШИ МУХАММАДА ОТ НАС ПРИВЕТСТВИЕ И МИР, И ВВЕДИ НАС В ОБИТЕЛЬ МИРА, О ОБЛАДАТЕЛЬ ВЕЛИЧИЯ И ЩЕДРОСТИ»<sup class=\"fn\">699</sup>."],["n",[[699,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Эта мольба не только является новшеством, но и содержит в себе противоречие Сунне. Речь идёт об обращении к Аллаху посредством права заповедной территории, Каабы, месяца, углов Каабы и Макама. И ханафиты прямо сказали о том, что эти слова являются нежелательными: «О Аллах! Поистине, я прошу Тебя посредством права заповедного места…» и т. д. См. одну из их книг \"Радд аль-мухтар\"». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 130; «аль-Манасик», стр. 57.</b>"],["sep",""],["p","ВОПРОС № 11: СЛОВА АЛЬ-БАДЖУРИ: «ЖЕЛАТЕЛЬНО (СУННА) ВЗЯТЬ ИЗ МУЗДАЛИФЫ КАМНИ, КОТОРЫЕ ПАЛОМНИК БУДЕТ БРОСАТЬ В ДЕНЬ ЖЕРТВОПРИНОШЕНИЯ. ЭТИХ КАМНЕЙ СЕМЬ. А КАМНИ ДЛЯ ВСЕХ ОСТАЛЬНЫХ БРОСАНИЙ ЖЕЛАТЕЛЬНО ВЗЯТЬ ИЗ ВАДИ МУХАССИР»<sup class=\"fn\">700</sup>."],["n",[[700,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Этому нет основы в Сунне. Возможно, он под «сунной» имел в виду сунну шейхов. И в этих рекомендациях, упомянутых им, ему противоречил аль-Газали, который сказал, что все камни желательно взять из Муздалифы. Всё это противоречит Сунне, как мы уже разъясняли».   </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 130; «аль-Манасик», стр. 57.</b>"],["sep",""],["h2","ГЛАВА № 7 – НОВШЕСТВА, СВЯЗАННЫЕ С БРОСАНИЕМ КАМЕШКОВ В СТОЛБЫ (ДЖАМАРАТ)"],["h2","ВОПРОС № 1: СОВЕРШЕНИЕ ПОЛНОГО ОМОВЕНИЯ (ГУСЛЬ) ПЕРЕД БРОСАНИЕМ КАМЕШКОВ"]],[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 131; «аль-Манасик», стр. 57.</b>"],["sep",""],["h2","ВОПРОС № 2: МЫТЬЁ КАМЕШКОВ ПЕРЕД ИХ БРОСАНИЕМ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 131; «аль-Манасик», стр. 57.</b>"],["sep",""],["p","ВОПРОС № 3: НЕКОТОРЫЕ ЛЮДИ ВО ВРЕМЯ БРОСАНИЯ КАМЕШКОВ ВМЕСТО СЛОВ «АЛЛАХУ АКБАР» ПРОИЗНОСЯТ «СУБХАНА ЛЛАХ» ИЛИ ДРУГИЕ ВИДЫ ПОМИНАНИЯ АЛЛАХА"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 131; «аль-Манасик», стр. 57.</b>"],["sep",""],["p","ВОПРОС № 4: НЕКОТОРЫЕ ЛЮДИ ПОСЛЕ ТАКБИРА ДОБАВЛЯЮТ: «ЧТОБЫ УНИЗИТЬ ШАЙТАНА И ЕГО ПАРТИЮ. О АЛЛАХ! СДЕЛАЙ МОЙ ХАДЖ БЛАГОЧЕСТИВЫМ, МОИ СТАРАНИЯ ВОЗНАГРАЖДЁННЫМИ, МОИ ГРЕХИ ПРОЩЁННЫМИ. О АЛЛАХ! С ВЕРОЙ В ТВОЮ КНИГУ И СЛЕДУЯ СУННЕ ТВОЕГО ПРОРОКА»."],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 131; «аль-Манасик», стр. 57.</b>"],["sep",""],["p","ВОПРОС № 5: СЛОВА АЛЬ-БАДЖУРИ: «ЖЕЛАТЕЛЬНО (СУННА) ВМЕСТЕ С БРОСАНИЕМ КАЖДОГО КАМЕШКА ГОВОРИТЬ: \"С ИМЕНЕМ АЛЛАХА! ПРЕВЕЛИК АЛЛАХ! АЛЛАХ ВЫПОЛНИЛ СВОЁ ОБЕЩАНИЕ…\" (И ТАК ДАЛЕЕ)»."],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 131; «аль-Манасик», стр. 57.</b>"],["sep",""],["p","ВОПРОС № 6: НЕКОТОРЫЕ ЛЮДИ ГОВОРЯТ, ЧТО НУЖНО БРОСАТЬ КАМЕШКИ ОПРЕДЕЛЕННЫМ ОБРАЗОМ. НАПРИМЕР, НЕКОТОРЫЕ ГОВОРЯТ: «НУЖНО ПОСТАВИТЬ КОНЧИК БОЛЬШОГО ПАЛЬЦА ПРАВОЙ РУКИ НА СЕРЕДИНУ УКАЗАТЕЛЬНОГО ПАЛЬЦА, ЗАТЕМ ПОЛОЖИТЬ КАМЕНЬ ПЕРЕД УКАЗАТЕЛЬНЫМ ПАЛЬЦЕМ И ШВЫРНУТЬ ЕГО». ДРУГИЕ ГОВОРЯТ: «УКАЗАТЕЛЬНЫЙ ПАЛЕЦ ВОЗЛАГАЕТСЯ НА СОЧЛЕНЕНИЕ БОЛЬШОГО ПАЛЬЦА, ОБРАЗУЯ ФОРМУ КОЛЬЦА…», И Т. Д<sup class=\"fn\">701</sup>."],["n",[[701,"Всё это является новшеством не потому, что запрещено бросать камешки таким образом. Однако проблема в том, что человек выделяет этот способ и называет его желательным, хотя у него никакого довода ни от пророка (да благословит его Аллах и приветствует), ни от сподвижников. Именно с этой стороны он впадает в религиозное новшество."]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 132; «аль-Манасик», стр. 58.</b>"],["sep",""],["p","ВОПРОС № 7: НЕКОТОРЫЕ ЛЮДИ ОГРАНИЧИВАЮТ МЕСТО, ОТКУДА РАЗРЕШЕНО БРОСАТЬ КАМЕШКИ. ОНИ ГОВОРЯТ, ЧТО МЕЖДУ ЧЕЛОВЕКОМ И СТОЛБОМ ДОЛЖНО БЫТЬ РАССТОЯНИЕ В ПЯТЬ ЛОКТЕЙ И БОЛЬШЕ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 132; «аль-Манасик», стр. 58.</b>"],["sep",""],["h2","ВОПРОС № 8: НЕКОТОРЫЕ ЛЮДИ БРОСАЮТ В СТОЛБЫ САНДАЛИИ (ВМЕСТО КАМНЕЙ)"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 132; «аль-Манасик», стр. 58.</b>"],["sep",""],["h2","ГЛАВА № 8 – НОВШЕСТВА, СВЯЗАННЫЕ С ЖЕРТВОПРИНОШЕНИЕМ И БРИТЬЁМ ГОЛОВЫ"],["p","ВОПРОС № 1: НЕКОТОРЫЕ ЛЮДИ ОТКАЗЫВАЮТСЯ ОТ ОБЯЗАТЕЛЬНОГО ЖЕРТВОПРИНОШЕНИЯ И ВМЕСТО ЭТОГО РАЗДАЮТ МИЛОСТЫНЮ РАЗМЕРОМ В ЦЕНУ ЖИВОТНОГО. ОНИ ДУМАЮТ, ЧТО В ЭТИ ДНИ В МЕККЕ ИТАК МНОГО МЯСА И ОНО ИСПОРТИТСЯ, И ПОЭТОМУ ОТ ЖЕРТВОПРИНОШЕНИЯ БУДЕТ МАЛАЯ ПОЛЬЗА<sup class=\"fn\">702</sup>"],["n",[[702,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«И это – одно из самых скверных новшеств, так как из-за этого люди аннулируют обряд, который утвержден в Коране и в Сунне, опираясь исключительно на своё личное мнение. К тому же в том, что люди не получают полную пользу от жертвенного мяса, виноваты те, кто приносят жертвы. Ведь это они не придерживаются советов мудрого шариата в вопросах жертвоприношения. Мы уже разъясняли этот вопрос». </i>"]]]],[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 132; «аль-Манасик», стр. 58.</b>"],["sep",""],["h2","ВОПРОС № 2: НЕКОТОРЫЕ ЛЮДИ, СОВЕРШАЯ ХАДЖ-ТАМАТТУ′<sup class=\"fn\">703</sup>, РЕЖУТ ЖЕРТВЕННЫХ ЖИВОТНЫХ (ХАДЬИ) ДО ДНЯ ЖЕРТВОПРИНОШЕНИЯ"],["n",[[703,"«Хадж ат-таматту′» заключается в том, что паломник сначала совершает малое паломничество (′умру), затем выходит из состояния ихрама, а затем, когда наступает время хаджа, он вновь вступает в ихрам и совершает хадж."]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 132; «аль-Манасик», стр. 58.</b>"],["sep",""],["h2","ВОПРОС № 3: НЕКОТОРЫЕ ПАЛОМНИКИ БРЕЮТ ГОЛОВУ, НАЧИНАЯ С ЛЕВОЙ СТОРОНЫ<sup class=\"fn\">704</sup>"],["n",[[704,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«В соответствии с Сунной начинать надо с правой стороны». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 133; «аль-Манасик», стр. 58.</b>"],["sep",""],["h2","ВОПРОС № 4: НЕКОТОРЫЕ ПАЛОМНИКИ ОГРАНИЧИВАЮТСЯ БРИТЬЁМ ЧЕТВЕРТИ ГОЛОВЫ<sup class=\"fn\">705</sup>"],["n",[[705,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Обязательно нужно обрить всю голову, ибо Всевышний Аллах сказал: </i><b>«…обрив головы и укоротив (волосы)…». </b><i>(Сура «аль-Фатх», аят 27). А пророк (да благословит его Аллах и приветствует) сказал: </i><b><i>\"Пусть Аллах помилует тех, кто побрил головы…\". </i></b><i>К тому же, если человек бреет только четверть головы, он прямо противоречит пророку (да благословит его Аллах и приветствует), который запретил «аль-каза′»</i><b>*</b><i>, сказав: </i><b><i>\"Либо побрейте голову целиком, либо не трогайте волосы\"».</i></b> <b>* ― </b> «Каза′» (<span class=\"ar-i\" lang=\"ar\" dir=\"rtl\">قزع</span>) - это такая причёска, когда человек сбривает часть волос, а другую часть оставляет."]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 133; «аль-Манасик», стр. 59.</b>"],["sep",""],["p","ВОПРОС № 5: АЛЬ-ГАЗАЛИ В КНИГЕ «АЛЬ-ИХЬЯ» СКАЗАЛ: «В СООТВЕТСТВИИ С СУННОЙ ВО ВРЕМЯ БРИТЬЯ ВОЛОС НУЖНО ОБРАТИТЬСЯ ЛИЦОМ К КААБЕ»."],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 133; «аль-Манасик», стр. 59.</b>"],["sep",""],["p","ВОПРОС № 6: НЕКОТОРЫЕ ЛЮДИ ВО ВРЕМЯ БРИТЬЯ ГОЛОВЫ ПРОИЗНОСЯТ СЛЕДУЮЩУЮ МОЛЬБУ: «ВСЯ ХВАЛА АЛЛАХУ ЗА ТО, ЧТО ОН НАСТАВИЛ НАС И ДАРОВАЛ НАМ МИЛОСТИ. О АЛЛАХ! ВОТ МОЙ ЧУБ В ТВОИХ РУКАХ, ТАК  ПРИМИ ЖЕ ОТ МЕНЯ И ПРОСТИ МНЕ МОИ ГРЕХИ! О АЛЛАХ! ЗАПИШИ МНЕ ЗА КАЖДЫЙ ВОЛОС БЛАГОЕ ДЕЯНИЕ…», И ТАК ДАЛЕЕ ДО КОНЦА МОЛЬБЫ"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 133; «аль-Манасик», стр. 59.</b>"],["sep",""],["h2","ВОПРОС № 7: РИТУАЛЬНЫЙ ОБХОД (ТАВАФ) ВОКРУГ ТЕХ МЕЧЕТЕЙ, КОТОРЫЕ НАХОДЯТСЯ ВОЗЛЕ СТОЛБОВ (ДЖАМАРАТ)"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 134; «аль-Манасик», стр. 59.</b>"],["sep",""],["h2","ВОПРОС № 8: НЕКОТОРЫЕ ЛЮДИ ГОВОРЯТ О ЖЕЛАТЕЛЬНОСТИ СОВЕРШЕНИЯ ПРАЗДНИЧНОЙ МОЛИТВЫ В ДЕНЬ ЖЕРТВОПРИНОШЕНИЯ В ДОЛИНЕ МИНА<sup class=\"fn\">706</sup>"],["n",[[706,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Сказал Ибн Теймия: \"Это – беспечное отношение к Сунне, потому что ни пророк (да благословит его Аллах и приветствует), ни его халифы никогда не совершали праздничную молитву в Мине\". (См. «аль-Кауа′ид ан-нурания», стр. 101). </i> <i>Также он сказал в «Маджму′», 2/385: \"В Мине не совершается праздничная молитва. Напротив, тем, кто находится в Мине, праздничную молитву заменяет бросание камешков в столбы\"». </i>"]]]],[["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 134; «аль-Манасик», стр. 59.</b>"],["sep",""],["p","ВОПРОС № 9: НЕКОТОРЫЕ ЛЮДИ, СОВЕРШАЯ ХАДЖ-ТАМАТТУ′, НЕ СОВЕРШАЮТ ПРОХОД МЕЖДУ САФОЙ И МАРВОЙ  (СА′Ю) ПОСЛЕ ТАВАФА АЛЬ-ИФАДА<sup class=\"fn\">707</sup>"],["n",[[707,"Таваф аль-ифада - обход по случаю праздника жертвоприношения, который является одним из важнейших обрядов хаджа. Здесь в примечаниях шейх аль-Альбани сказал: <i>«Как мы уже приводили, пророк (да благословит его Аллах и приветствует) повелел совершать са′ю после этого тавафа». </i>"]]],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 134; «аль-Манасик», стр. 59.</b>"],["sep",""],["h2","ГЛАВА № 9 – НОВШЕСТВА, СВЯЗАННЫЕ С ПРОЩАЛЬНЫМ ТАВАФОМ И НЕКОТОРЫМИ ДРУГИМИ ВОПРОСАМИ"],["h2","ВОПРОС № 1: ПРАЗДНОВАНИЕ ОБЛАЧЕНИЯ КААБЫ В НОВОЕ ПОКРЫВАЛО (КИСВА)"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 134; «аль-Манасик», стр. 59.</b>"],["sep",""],["h2","ВОПРОС № 2: ОБЛАЧЕНИЕ В ПОКРЫВАЛО (КИСВА) МЕСТА СТОЯНИЯ ИБРАХИМА (МАКАМУ ИБРАХИМ)"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 134; «аль-Манасик», стр. 59.</b>"],["sep",""],["p","ВОПРОС № 3: НЕКОТОРЫЕ ЛЮДИ ПОДВЯЗЫВАЮТ ТРЯПКИ К МЕСТУ СТОЯНИЯ ИБРАХИМА (МАКАМУ ИБРАХИМ) ИЛИ К МИНБАРУ, ЧТОБЫ БЫЛИ УДОВЛЕТВОРЕНЫ ИХ НУЖДЫ<sup class=\"fn\">708</sup>"],["n",[[708,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Подобного стало много в последнее время, хотя раньше этого не было. Это указывает на то, что государство единобожия стало небрежно относиться к уничтожению того, что несовместимо с единобожием, которое является самой ценной вещью в этой стране. Это же касается шейхов и тех, кто занимается повелением одобряемого, кроме тех, кого Аллах пожелал укрепить!».  </i>"]]],["sep",""],["h2","ВОПРОС № 4: НЕКОТОРЫЕ ПАЛОМНИКИ ПИШУТ СВОИ ИМЕНА НА СТЕНАХ КААБЫ ИЛИ ЗАВЕЩАЮТ ДРУГИМ ЗАПИСАТЬ ИХ ИМЕНА"],["p","<b>См. «Хадж пророка (да благословит его Аллах и приветствует)», стр. 135; «аль-Манасик», стр. 59.</b>"],["sep",""],["p","ВОПРОС № 5: НЕКОТОРЫЕ ЛЮДИ СЧИТАЮТ, ЧТО ЗАПОВЕДНОЙ МЕЧЕТИ (АЛЬ-МАСДЖИД АЛЬ-ХАРАМ) РАЗРЕШЕНО ПРОХОДИТЬ ПЕРЕД МОЛЯЩИМИСЯ, И ЕСЛИ КТО-ТО ИЗ МОЛЯЩИХСЯ ПОПЫТАЕТСЯ ПОМЕЩАТЬ ИМ ПРОЙТИ, ОНИ ОТВЕЧАЮТ ЕМУ СИЛОЙ<sup class=\"fn\">709</sup>"],["n",[[709,"Здесь в примечаниях шейх аль-Альбани сказал: <i>«Да, об этом сказали некоторые обладатели знания, но нет сомнений в том, что это противоречит Сунне. Ведь пришли хадисы о запрете проходить перед молящимся и хадисы, содержащие веление отталкивать того, кто пытается пройти перед молящимся, и они являются общими, и включают в себя всех молящихся во всех мечетях. Доводы же тех, кто исключают из этого запрета Мекку, не годятся. Они опираются на хадис аль-Мутталиба ибн Уада′и, который сообщил, что видел, как пророк (да благословит его Аллах и приветствует) совершал молитву, и между ним и Каабой не было преграды (сутра), а люди проходили перед ним. Во-первых, этот хадис не говорит прямо о том, что они проходили близко и прямо перед ним. А, во-вторых, его цепочка (иснад) является слабой, как я разъяснил это в \"ас-Сильсиля\", № 932». </i>"]]]]];
